begin;
create table public.bizctrl_public_demo_catalog (
  catalog_key text primary key check (catalog_key = 'businesses-v1'),
  payload jsonb not null check (jsonb_typeof(payload) = 'object' and payload @> '{"synthetic":true}'::jsonb),
  published_at timestamptz not null default now()
);
comment on table public.bizctrl_public_demo_catalog is 'Public synthetic catalog only. No tenant data, user accounts, financial records or operational references. Never use for accounting.';
alter table public.bizctrl_public_demo_catalog enable row level security;
revoke all on table public.bizctrl_public_demo_catalog from public, anon, authenticated;
grant select on table public.bizctrl_public_demo_catalog to anon, authenticated;
create policy demo_catalog_read_only on public.bizctrl_public_demo_catalog for select to anon, authenticated using (catalog_key = 'businesses-v1' and payload @> '{"synthetic":true}'::jsonb);
